import { test } from "node:test";
import assert from "node:assert/strict";
import { min, max, mean } from "../src/stats.js";

test("min returns the smallest value", () => assert.equal(min([3, 1, 2]), 1));
test("max returns the largest value", () => assert.equal(max([3, 1, 2]), 3));
test("mean returns the arithmetic mean", () => assert.equal(mean([1, 2, 3, 4]), 2.5));
